            digit = int(char)

            # Skip if last digit is 0
            if digit == 0:
                continue

            # d = 1, 2, 5: All substrings ending at j are divisible
            if digit in (1, 2, 5):
                ans += (j + 1)

            # d = 3, 6: Divisible by 3
            # P_j = (P_{j-1} + digit) % 3
            # Condition: P_j == P_{i-1}
            current_p3 = (current_p3 + digit) % 3
            if digit in (3, 6):
                ans += freq3.get(current_p3, 0)
            freq3[current_p3] = freq3.get(current_p3, 0) + 1

            # d = 4: Divisible by 4 depends on last 2 digits
            if digit == 4:
                if j >= 1:
                    val2 = int(s[j-1:j+1])
                    if val2 % 4 == 0:
                        ans += (j + 1)
                    else:
                        ans += 1
                else:
                    ans += 1

            # d = 7: Coprime logic
